"""Displacement threshold theta = 1/(1-alpha) and the share of the U(2, 5) sigma_ai prior below it.

Referee concern 2. Pure arithmetic; no simulation.

Run from the repo root:
    .venv/bin/python scripts/threshold_table.py
Writes data/threshold_table.md.
"""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "data" / "threshold_table.md"
ALPHAS = (0.60, 0.64, 0.70, 0.75, 0.80, 0.85)
LO, HI = 2.0, 5.0


def main() -> None:
    L = ["# Displacement threshold by span-of-control parameter", "",
         "Generated by `scripts/threshold_table.py`. theta = 1/(1 - alpha); share = P(sigma_ai < theta) under U(2, 5).", "",
         "| alpha | theta | share of U(2,5) below theta |", "|---|---|---|"]
    for a in ALPHAS:
        th = 1.0 / (1.0 - a)
        share = min(1.0, max(0.0, (th - LO) / (HI - LO)))
        L.append(f"| {a:.2f} | {th:.3f} | {share:.1%} |")
    OUT.write_text("\n".join(L) + "\n")
    print(OUT.read_text())


if __name__ == "__main__":
    main()
